#ifndef CASTRONOMIADATA_H
#define CASTRONOMIADATA_H

#include <stddef.h>
#include <stdint.h>

// Built-in data for Astronomia, generated by Scripts/generate-ephemeris-data.py.
//
// The data is C arrays because the C compiler turns them into read-only data in seconds,
// where the same values as Swift array literals take minutes to compile.
//
// Each series has its terms in order of decreasing amplitude, scaled by the largest power of
// time of the span, and gives the number of leading terms kept at each of the five precision
// levels, the first every term. A coarser level keeps the terms whose scaled amplitude is at
// least its threshold, so its terms are the first of a finer level's.

/// The number of precision levels.
#define ASTRONOMIA_PRECISION_LEVELS 5

// Series of the VSOP planetary theories, whose terms have arguments linear in time:
// T^α (S sin(φ + ν T) + C cos(φ + ν T)). VSOP87's terms, T^α A cos(B + C T), take the same
// form with S = 0.

/// A series: the terms of one variable with the same power of time α.
struct astronomia_vsop_series {
	/// The variable, numbered from 1.
	int32_t variable;
	/// The power of time α.
	int32_t power;
	/// The number of leading terms at each precision level, the first every term.
	int32_t counts[ASTRONOMIA_PRECISION_LEVELS];
};

/// A term T^α (S sin(φ + ν T) + C cos(φ + ν T)).
struct astronomia_vsop_term {
	/// The phase φ.
	double phase;
	/// The frequency ν.
	double frequency;
	/// The coefficient of the sine, S.
	double s;
	/// The coefficient of the cosine, C.
	double c;
};

/// The series of one body, with their terms in one array, series by series.
struct astronomia_vsop_series_data {
	/// The number of series.
	size_t series_count;
	/// The series.
	const struct astronomia_vsop_series *series;
	/// The number of terms, the sum of the series' counts.
	size_t term_count;
	/// The terms of every series, in the order of the series.
	const struct astronomia_vsop_term *terms;
	/// The first Julian epoch of the span the series are truncated for.
	double start_epoch;
	/// The last Julian epoch of the span.
	double end_epoch;
	/// The threshold of each precision level.
	double thresholds[ASTRONOMIA_PRECISION_LEVELS];
};

// VSOP2013 heliocentric elliptic elements, from J1000.0 to J3000.0
extern const struct astronomia_vsop_series_data astronomia_vsop2013_mercury;
extern const struct astronomia_vsop_series_data astronomia_vsop2013_venus;
extern const struct astronomia_vsop_series_data astronomia_vsop2013_earth_moon_barycenter;
extern const struct astronomia_vsop_series_data astronomia_vsop2013_mars;
extern const struct astronomia_vsop_series_data astronomia_vsop2013_jupiter;
extern const struct astronomia_vsop_series_data astronomia_vsop2013_saturn;
extern const struct astronomia_vsop_series_data astronomia_vsop2013_uranus;
extern const struct astronomia_vsop_series_data astronomia_vsop2013_neptune;
extern const struct astronomia_vsop_series_data astronomia_vsop2013_pluto;

// Series of the lunar theory ELP/MPP02, whose terms have arguments that are sums of integer
// multiples of fundamental arguments, polynomials in time. The terms keep their multipliers,
// because the fundamental arguments depend on the fit of the solution.

/// A series: the terms of one variable with the same power of time α.
struct astronomia_elp_series {
	/// The variable, numbered from 1: longitude, latitude, distance.
	int32_t variable;
	/// The power of time α.
	int32_t power;
	/// The number of leading terms at each precision level, the first every term.
	int32_t counts[ASTRONOMIA_PRECISION_LEVELS];
};

/// A term of the main problem, A sin(Σ iₖ Dₖ) in longitude and latitude and A cos(Σ iₖ Dₖ) in
/// distance, where D₁ to D₄ are the Delaunay arguments D, F, l, l'.
struct astronomia_elp_main_term {
	/// The amplitude A, before the corrections of the fit.
	double amplitude;
	/// The partial derivatives B₁ to B₅ of the amplitude, which correct it for the fit.
	double partials[5];
	/// The multipliers iₖ of D, F, l, l'.
	int8_t multipliers[4];
};

/// A term of the perturbations, T^α (S sin(Σ iₖ Aₖ) + C cos(Σ iₖ Aₖ)), where A₁ to A₁₃ are the
/// Delaunay arguments D, F, l, l', the mean longitudes of Mercury to Neptune, and ζ.
struct astronomia_elp_perturbation_term {
	/// The coefficient of the sine, S.
	double s;
	/// The coefficient of the cosine, C.
	double c;
	/// The multipliers iₖ of the thirteen arguments.
	int8_t multipliers[13];
};

/// The series of the main problem and of the perturbations, with their terms in the order of
/// the series.
struct astronomia_elp_series_data {
	/// The number of series of the main problem.
	size_t main_series_count;
	/// The series of the main problem.
	const struct astronomia_elp_series *main_series;
	/// The number of terms of the main problem, the sum of the series' counts.
	size_t main_term_count;
	/// The terms of the main problem.
	const struct astronomia_elp_main_term *main_terms;
	/// The number of series of the perturbations.
	size_t perturbation_series_count;
	/// The series of the perturbations.
	const struct astronomia_elp_series *perturbation_series;
	/// The number of terms of the perturbations, the sum of the series' counts.
	size_t perturbation_term_count;
	/// The terms of the perturbations.
	const struct astronomia_elp_perturbation_term *perturbation_terms;
	/// The first Julian epoch of the span the series are truncated for.
	double start_epoch;
	/// The last Julian epoch of the span.
	double end_epoch;
	/// The threshold for longitude and latitude at each precision level, in arcseconds.
	double angle_thresholds[ASTRONOMIA_PRECISION_LEVELS];
	/// The threshold for distance at each precision level, in kilometers.
	double distance_thresholds[ASTRONOMIA_PRECISION_LEVELS];
};

// ELP/MPP02 geocentric lunar coordinates, from J1000.0 to J3000.0
extern const struct astronomia_elp_series_data astronomia_elpmpp02;

// Series of the IAU 2006 precession and IAU 2000A_R06 nutation, from the tables of the IERS
// Conventions (2010), Chapter 5. The terms have arguments that are sums of integer multiples
// of fourteen fundamental arguments, polynomials in time: the Delaunay arguments l, l', F, D,
// and Ω, the mean longitudes of Mercury to Neptune, and the general precession in longitude
// p_A. Coefficients are in microarcseconds, and t is TT in Julian centuries from J2000.0.

/// A series: the terms with the same power of time j.
struct astronomia_iau_series {
	/// The power of time j.
	int32_t power;
	/// The number of leading terms at each precision level, the first every term.
	int32_t counts[ASTRONOMIA_PRECISION_LEVELS];
};

/// A term t^j (S sin(Σ iₖ Aₖ) + C cos(Σ iₖ Aₖ)), where A₁ to A₁₄ are the fundamental
/// arguments.
struct astronomia_iau_term {
	/// The coefficient of the sine, S, in microarcseconds.
	double s;
	/// The coefficient of the cosine, C, in microarcseconds.
	double c;
	/// The multipliers iₖ of l, l', F, D, Ω, Mercury to Neptune, and p_A.
	int8_t multipliers[14];
};

/// The polynomial part and series of one table, with the series' terms in one array, series by
/// series, and the truncations they were generated with.
struct astronomia_iau_series_data {
	/// The coefficients of t⁰ to t⁵ of the polynomial part, in microarcseconds.
	double polynomial[6];
	/// The number of series.
	size_t series_count;
	/// The series.
	const struct astronomia_iau_series *series;
	/// The number of terms, the sum of the series' counts.
	size_t term_count;
	/// The terms of every series, in the order of the series.
	const struct astronomia_iau_term *terms;
	/// The threshold of each precision level, below which terms are left out, in
	/// microarcseconds, at the largest |t| of the span.
	double thresholds[ASTRONOMIA_PRECISION_LEVELS];
	/// The first Julian epoch of the span.
	double start_epoch;
	/// The last Julian epoch of the span.
	double end_epoch;
};

// IAU 2006/2000A_R06 series
extern const struct astronomia_iau_series_data astronomia_iau2006_nutation_longitude;
extern const struct astronomia_iau_series_data astronomia_iau2006_nutation_obliquity;
extern const struct astronomia_iau_series_data astronomia_iau2006_s_plus_half_xy;

// Evaluate an IAU 2006 series at the requested precision level
double astronomia_iau_evaluate_series(const struct astronomia_iau_series *series, size_t series_count, const struct astronomia_iau_term *terms, size_t term_count, const double arguments[14], double t, int32_t level);

#endif
